10	  const [amount, setAmount] = useState('');
11	
12	  async function load() {
13	    const res = await fetch(`/api/projects/${projectId}/invoices`);
14	    if (res.ok) {
15	      setInvoices(await res.json());
16	    }
17	  }
18	
